fixed.td64_reported_semantics_pandas_probe:
import numpy as np
import pandas as pd
import warnings

np_half = np.iinfo(np.int64).max // 2
half = np_half
arr = np.array([half, half, half], dtype='m8[ns]')
df_over = pd.DataFrame({'a': arr, 'b': arr, 'c': arr})

def run_case_df(axis, skipna):
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter('always')
        try:
            res = df_over.sum(axis=axis, skipna=skipna)
            out = {
                'kind': 'value',
                'dtype': str(res.dtype),
                'all_nan': getattr(res, 'isna', lambda: pd.Series([False]*len(res))).all() if hasattr(res,'isna') else None,
                'values': res.to_numpy().astype('int64', copy=False) if res.dtype.kind in ['m','M'] else None,
                'nanat_count': int(getattr(res, 'isna', lambda: pd.Series([False]*len(res))).sum()) if hasattr(res,'isna') else None,
                'warnings': [str(x.message) for x in w],
                'runtime_warning_present': any('overflow' in str(x.message).lower() for x in w),
            }
            return out
        except Exception as e:
            out = {
                'kind': 'exception',
                'exc_type': type(e).__name__,
                'exc_msg': str(e),
                'warnings': [str(x.message) for x in w],
            }
            return out

axes = [0,1]
skips = [True, False]
results = {}
for axis in axes:
    for skipna in skips:
        key = f'df_over.sum_axis{axis}_skipna{skipna}'
        results[key] = run_case_df(axis, skipna)

ser_nat = pd.Series(np.array(['NaT','NaT','NaT'], dtype='m8[ns]'))

def run_case_ser_skipna_false():
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter('always')
        try:
            res = ser_nat.sum(skipna=False)
            return {
                'kind':'value',
                'dtype': str(getattr(res,'dtype', None)),
                'isna': pd.isna(res),
                'value': str(res),
                'warnings':[str(x.message) for x in w],
            }
        except Exception as e:
            return {
                'kind':'exception',
                'exc_type': type(e).__name__,
                'exc_msg': str(e),
                'warnings':[str(x.message) for x in w],
            }

nat = np.array(['NaT','NaT','NaT'], dtype='m8[ns]')
df_nat = pd.DataFrame({'a': nat, 'b': nat, 'c': nat})

def run_case_df_nat(axis):
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter('always')
        try:
            res = df_nat.sum(axis=axis, skipna=False)
            out = {
                'kind':'value',
                'dtype': str(res.dtype),
                'all_na': bool(res.isna().all()),
                'values_as_str': [str(x) for x in res.to_numpy()],
                'warnings':[str(x.message) for x in w],
            }
            return out
        except Exception as e:
            return {
                'kind':'exception',
                'exc_type': type(e).__name__,
                'exc_msg': str(e),
                'warnings':[str(x.message) for x in w],
            }

results['ser_nat.sum_skipnaFalse'] = run_case_ser_skipna_false()
for axis in [0,1]:
    results[f'df_nat.sum_axis{axis}_skipnaFalse'] = run_case_df_nat(axis)

for k,v in results.items():
    probe(k, v)

